 [ProfileSqlFact] public async Task PerTicketRefundsRespectExplicitPaidSharesAndPostponementPreservesCash() {
  await using var f=await LifecycleFixture.Create();var pay=await f.Tx("Expense","100");var refund=await f.Tx("Refund","30",pay);
  var ticket=new ConcertTicket(Guid.NewGuid().ToString(),"A","1排1座","本人","Electronic","Received",PaidShare:"40");var second=ticket with{Id=Guid.NewGuid().ToString(),Seat="1排2座",PaidShare="60"};
  var order=Order() with{State="Issued",Quantity=2,PaidOn=new(2026,1,1),PaidAmount="100",PaymentTransactionId=pay,Tickets=[ticket,second]};var scene=Scene() with{Orders=[order]};
  var result=await Data(await Write(f.Client,"/concerts",scene));var id=result.GetProperty("id").GetString()!;var version=result.GetProperty("version").GetString()!;
  var r=new ConcertRefund(Guid.NewGuid().ToString(),"ticket:"+order.Id,"Partial","30","10",refund,"30","退第一张部分票款",ticket.Id);scene=scene with{Refunds=[r]};
  result=await Data(await Write(f.Client,"/concerts/"+id,scene,version,put:true));version=result.GetProperty("version").GetString()!;var count=await f.Db.Transactions.CountAsync();
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/"+id,scene with{Refunds=[r with{RequestedAmount="31"}]},version,put:true)).StatusCode);
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/"+id,scene with{Refunds=[r with{TicketId=Guid.NewGuid().ToString()}]},version,put:true)).StatusCode);
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/"+id,scene with{Orders=[order with{Tickets=[ticket with{PaidShare="20"},second]}]},version,put:true)).StatusCode);
  scene=scene with{State="Postponed",StartsAt=new(2026,12,20,20,0,0,TimeSpan.FromHours(8)),Orders=[order with{State="Postponed"}]};result=await Data(await Write(f.Client,"/concerts/"+id,scene,version,put:true));version=result.GetProperty("version").GetString()!;
  var detail=await Data(await f.Client.GetAsync("/api/concerts/"+id));Assert.Equal("70.00",detail.GetProperty("report").GetProperty("personalNetCost").GetString());Assert.Equal("Received",detail.GetProperty("input").GetProperty("orders")[0].GetProperty("tickets")[0].GetProperty("state").GetString());Assert.Equal(count,await f.Db.Transactions.CountAsync());
  // A client predating the optional fields must preserve the established attribution.
  result=await Data(await Write(f.Client,"/concerts/"+id,scene with{Refunds=[r with{TicketId=null}],Orders=[scene.Orders[0] with{Tickets=[ticket with{PaidShare=null},second]}]},version,put:true));version=result.GetProperty("version").GetString()!;
  detail=await Data(await f.Client.GetAsync("/api/concerts/"+id));Assert.Equal(ticket.Id,detail.GetProperty("input").GetProperty("refunds")[0].GetProperty("ticketId").GetString());
  scene=scene with{State="Upcoming",Orders=[order]};await Data(await Write(f.Client,"/concerts/"+id,scene,version,put:true));Assert.Equal(count,await f.Db.Transactions.CountAsync());
 }
 [ProfileSqlFact] public async Task InsuranceUnusedBurdenAndClosingNeverDuplicateExpenseOrInventRecovery() {
  await using var f=await LifecycleFixture.Create();var pay=await f.Tx("Expense","100");var income=await f.Tx("Income","30");var ticket=new ConcertTicket(Guid.NewGuid().ToString(),"A","1排1座","本人","Electronic","Received",PaidShare:"100",Outcome:new("Unused","未到场"));var order=Order() with{State="Issued",Quantity=1,PaidOn=new(2026,1,1),PaidAmount="100",PaymentTransactionId=pay,Tickets=[ticket]};
  var claim=new ConcertInsurance(Guid.NewGuid().ToString(),ticket.Id,"测试保险","POLICY-TEST","30","Open",[],[],"");var scene=Scene() with{Orders=[order],Insurance=[claim]};var result=await Data(await Write(f.Client,"/concerts",scene));var id=result.GetProperty("id").GetString()!;var version=result.GetProperty("version").GetString()!;
  async Task<JsonElement> Detail()=>await Data(await f.Client.GetAsync("/api/concerts/"+id));async Task Save(ConcertInput next){result=await Data(await Write(f.Client,"/concerts/"+id,next,version,put:true));version=result.GetProperty("version").GetString()!;scene=next;}
  var report=(await Detail()).GetProperty("report");Assert.Equal("100.00",report.GetProperty("unusedBurden").GetString());Assert.Equal("100.00",report.GetProperty("finalPersonalCost").GetString());
  var close=new ConcertClosing("Closed",new(2026,1,21),"逐项核对");Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/"+id,scene with{Closing=close},version,put:true)).StatusCode);
  claim=claim with{State="Settled",Receipts=[new(income,"30")]};await Save(scene with{Insurance=[claim]});report=(await Detail()).GetProperty("report");Assert.Equal("70.00",report.GetProperty("unusedBurden").GetString());Assert.Equal("70.00",report.GetProperty("finalPersonalCost").GetString());Assert.Equal("100.00",report.GetProperty("actual").GetString());
  var count=await f.Db.Transactions.CountAsync();await Save(scene with{Closing=close});Assert.Equal(count,await f.Db.Transactions.CountAsync());
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/"+id,scene with{Title="结案后修改"},version,put:true)).StatusCode);
  f.Db.ChangeTracker.Clear();var changed=await f.Db.Transactions.SingleAsync(t=>t.Id==income);changed.Status="NeedsReview";await f.Db.SaveChangesAsync();report=(await Detail()).GetProperty("report");Assert.True(report.GetProperty("closingReviewRequired").GetBoolean());Assert.Equal("100.00",report.GetProperty("finalPersonalCost").GetString());changed.Status="Confirmed";await f.Db.SaveChangesAsync();
  await Save(scene with{Closing=close with{State="Open"}});
  var sale=new ConcertTicketTransfer("本人","买家",new(2026,1,2),"30","Recorded",[new(income,"30")],[],"",true);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/"+id,scene with{Orders=[order with{Tickets=[ticket with{Transfer=sale}]}]},version,put:true)).StatusCode);
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/"+id,scene with{Insurance=[claim with{State="Revoked"}]},version,put:true)).StatusCode);
  var back=await f.Tx("Expense","30");claim=claim with{State="Revoked",Returns=[new(back,"30")]};await Save(scene with{Insurance=[claim]});Assert.Equal("100.00",(await Detail()).GetProperty("report").GetProperty("finalPersonalCost").GetString());
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/"+id,scene with{Costs=[new(Guid.NewGuid().ToString(),"Insurance",back,null,"1","本人","本人")]},version,put:true)).StatusCode);
 }
 [ProfileSqlFact] public async Task GiftTicketsCanBeIssuedWithoutInventingPayment() {
  await using var f=await LifecycleFixture.Create();var origin=new ConcertTicketOrigin("Gift","朋友",new(2026,1,1),"免费获赠",true);var ticket=new ConcertTicket(Guid.NewGuid().ToString(),"A","1排1座","本人","Electronic","Received",PaidShare:"0");var order=Order() with{Number="FREE-GIFT",State="Issued",Quantity=1,PaidAmount="0",FacePrice="100",Origin=origin,Tickets=[ticket]};var scene=Scene() with{Orders=[order]};var count=await f.Db.Transactions.CountAsync();var saved=await Data(await Write(f.Client,"/concerts",scene));var id=saved.GetProperty("id").GetString()!;
  var report=(await Data(await f.Client.GetAsync("/api/concerts/"+id))).GetProperty("report");Assert.Equal("0.00",report.GetProperty("personalNetCost").GetString());Assert.Equal(count,await f.Db.Transactions.CountAsync());
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts",scene with{Orders=[order with{Id=Guid.NewGuid().ToString(),Number="INVALID-GIFT",Origin=origin with{PlatformAllowed=false}}]})).StatusCode);
  var income=await f.Tx("Income","30");var transfer=new ConcertTicketTransfer("本人","买家",new(2026,1,2),"30","Recorded",[new(income,"30")],[],"",true);scene=scene with{Orders=[order with{Tickets=[ticket with{Transfer=transfer}]}]};await Data(await Write(f.Client,"/concerts/"+id,scene,saved.GetProperty("version").GetString()!,put:true));report=(await Data(await f.Client.GetAsync("/api/concerts/"+id))).GetProperty("report");Assert.Equal("-30.00",report.GetProperty("finalPersonalCost").GetString());
 }
 [ProfileSqlFact] public async Task FutureConfirmedLedgerSourcesCannotBecomeOccurredConcertCostOrRefund() {
  await using var f=await LifecycleFixture.Create();var date=DateTimeOffset.UtcNow.AddDays(2);var tx=await f.Tx("Expense","100");f.Db.ChangeTracker.Clear();var changed=await f.Db.Transactions.SingleAsync(t=>t.Id==tx);changed.OccurredAt=date;await f.Db.SaveChangesAsync();
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts",Scene() with{Costs=[new(Guid.NewGuid().ToString(),"Ticket",tx,null,"100","本人","本人")]})).StatusCode);
  var item=new InterestItem(Guid.NewGuid().ToString(),"未来来源商品",null,"其他","",1,"100","0","0","0","100","Daily","Held",[]);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/interests/purchases",new InterestPurchase(new(2026,1,1),"CNY","","","FUTURE",tx,null,"Daily","Purchased",[item],[],[],""))).StatusCode);
  var pay=await f.Tx("Expense","100");var refund=await f.Tx("Refund","30",pay);f.Db.ChangeTracker.Clear();var r=await f.Db.Transactions.SingleAsync(t=>t.Id==refund);r.OccurredAt=date;await f.Db.SaveChangesAsync();var cost=new ConcertCost(Guid.NewGuid().ToString(),"Ticket",pay,null,"100","本人","本人");Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts",Scene() with{Costs=[cost],Refunds=[new(Guid.NewGuid().ToString(),cost.Id,"Partial","30","0",refund,"30","")]})).StatusCode);
 }
 [ProfileSqlFact] public async Task OtherPaidPayablesRefundsAndPartialRepaymentsReconcileWithoutFakeCash() {
  await using var f=await LifecycleFixture.Create();var date=new DateTimeOffset(2026,1,1,10,0,0,TimeSpan.FromHours(8));var input=new ConcertPayableInput("实际代付人","CNY","100",f.Expense.Id,date,"实际付款事实",true);
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/payables",input with{Confirmed=false})).StatusCode);var key=Guid.NewGuid().ToString();var result=await Data(await Write(f.Client,"/concerts/payables",input,key:key));var business=result.GetProperty("businessId").GetString()!;var tx=result.GetProperty("transactionId").GetString()!;
  Assert.Equal(tx,(await Data(await Write(f.Client,"/concerts/payables",input,key:key))).GetProperty("transactionId").GetString());Assert.Equal("0.00",result.GetProperty("cashImpact").GetString());
  async Task<decimal> Cash()=>await f.Db.Entries.Where(e=>e.UserId==f.User.Id && e.AccountId==f.Cash.Id && e.Kind=="Account").SumAsync(e=>(decimal?)e.Amount)??0;
  Assert.Equal(0,await Cash());var order=Order() with{Number="OTHER-PAID",PaidAmount="100",PaidOn=new(2026,1,1),PaymentTransactionId=tx,State="Issued"};var scene=Scene() with{Orders=[order]};var saved=await Data(await Write(f.Client,"/concerts",scene));var id=saved.GetProperty("id").GetString()!;var version=saved.GetProperty("version").GetString()!;
  async Task<JsonElement> Detail()=>await Data(await f.Client.GetAsync("/api/concerts/"+id));async Task Save(ConcertInput next){saved=await Data(await Write(f.Client,"/concerts/"+id,next,version,put:true));version=saved.GetProperty("version").GetString()!;scene=next;}
  Assert.Equal("100.00",(await Detail()).GetProperty("report").GetProperty("pendingPayables").GetString());Assert.Equal("100.00",(await Detail()).GetProperty("report").GetProperty("personalNetCost").GetString());
  var closed=new ConcertClosing("Closed",new(2026,1,21),"");Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/"+id,scene with{Closing=closed},version,put:true)).StatusCode);
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts",scene with{Orders=[order with{Id=Guid.NewGuid().ToString(),Number="DUPLICATE-PAYABLE"}]})).StatusCode);
  result=await Data(await Write(f.Client,"/concerts/payables/"+business+"/refund",new ConcertPayableRefund("20",date.AddDays(1),"退至代付人",true),"1"));var refund=result.GetProperty("transactionId").GetString()!;var bv=result.GetProperty("version").GetString()!;
  var r=new ConcertRefund(Guid.NewGuid().ToString(),"ticket:"+order.Id,"Partial","20","0",refund,"20","");await Save(scene with{Refunds=[r]});Assert.Equal(0,await Cash());Assert.Equal("80.00",(await Detail()).GetProperty("report").GetProperty("pendingPayables").GetString());Assert.Equal("80.00",(await Detail()).GetProperty("report").GetProperty("personalNetCost").GetString());
  await Data(await Write(f.Client,"/business/"+business+"/settlements",new SettlementInput(f.Cash.Id,"30",date.AddDays(2)),bv));bv=(await Data(await f.Client.GetAsync("/api/business/"+business))).GetProperty("version").GetString()!;Assert.Equal(-30,await Cash());Assert.Equal("50.00",(await Detail()).GetProperty("report").GetProperty("pendingPayables").GetString());
  result=await Data(await Write(f.Client,"/concerts/payables/"+business+"/refund",new ConcertPayableRefund("10",date.AddDays(3),"实际退至本人",true,f.Cash.Id),bv));bv=result.GetProperty("version").GetString()!;var cashRefund=result.GetProperty("transactionId").GetString()!;
  await Save(scene with{Refunds=[r,new(Guid.NewGuid().ToString(),r.CostId,"Partial","10","0",cashRefund,"10","")]});Assert.Equal(-20,await Cash());Assert.Equal("50.00",(await Detail()).GetProperty("report").GetProperty("pendingPayables").GetString());Assert.Equal("70.00",(await Detail()).GetProperty("report").GetProperty("personalNetCost").GetString());
  await Data(await Write(f.Client,"/business/"+business+"/settlements",new SettlementInput(f.Cash.Id,"50",date.AddDays(4)),bv));Assert.Equal(-70,await Cash());Assert.Equal("0.00",(await Detail()).GetProperty("report").GetProperty("pendingPayables").GetString());await Save(scene with{Closing=closed});
  Assert.Equal(70,await f.Db.Entries.Where(e=>e.UserId==f.User.Id && e.Kind=="Expense").SumAsync(e=>e.Amount));Assert.Equal(0,await f.Db.Entries.Where(e=>e.UserId==f.User.Id && e.Kind=="Income").SumAsync(e=>(decimal?)e.Amount)??0);
  var paidBack=await f.Db.Transactions.AsNoTracking().SingleAsync(t=>t.BusinessId==business && t.Type=="LoanRepaymentPaid" && t.Amount==50);bv=(await Data(await f.Client.GetAsync("/api/business/"+business))).GetProperty("version").GetString()!;
  await Data(await Write(f.Client,"/business/"+business+"/transactions/"+paidBack.Id+"/delete",new{},bv));var changedReport=(await Detail()).GetProperty("report");Assert.True(changedReport.GetProperty("closingReviewRequired").GetBoolean());Assert.Equal("50.00",changedReport.GetProperty("pendingPayables").GetString());Assert.Equal("70.00",changedReport.GetProperty("personalNetCost").GetString());
  await using var other=await LifecycleFixture.Create();Assert.Empty((await Data(await other.Client.GetAsync("/api/concerts/payables?currency=CNY"))).EnumerateArray());Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(other.Client,"/concerts/payables/"+business+"/refund",new ConcertPayableRefund("1",date.AddDays(3),"",true),"1")).StatusCode);
 }
 [ProfileSqlFact] public async Task AdvanceTransferSettlementIsNeverCountedAgainAsPersonalRecovery() {
  await using var f=await LifecycleFixture.Create();var date=new DateTimeOffset(2026,1,1,10,0,0,TimeSpan.FromHours(8));var advance=await Data(await Write(f.Client,"/advances",new AdvanceInput("组合门票","朋友",f.Cash.Id,"100","40",date,CategoryId:f.Expense.Id)));var business=advance.GetProperty("businessId").GetString()!;var advanceId=advance.GetProperty("id").GetString()!;var own=advance.GetProperty("ownTransactionId").GetString()!;var original=await f.Db.Transactions.AsNoTracking().SingleAsync(t=>t.BusinessId==business && t.Type=="ReimbursementAdvance");
  await Data(await Write(f.Client,"/advances/"+advanceId+"/settle",new SettlementInput(f.Cash.Id,"60",date.AddDays(1)),advance.GetProperty("version").GetString()!));var settlement=await f.Db.Transactions.AsNoTracking().SingleAsync(t=>t.BusinessId==business && t.Type=="ReimbursementReceived");var income=await f.Tx("Income","20");
  var transfer=new ConcertTicketTransfer("本人","朋友",new(2026,1,2),"80","Recorded",[new(income,"20"),new(settlement.Id,"60")],[],"",true);var ticket=new ConcertTicket(Guid.NewGuid().ToString(),"A","1排1座","朋友","Electronic","Received",Transfer:transfer,PaidShare:"100");var order=Order() with{Number="MIXED-TRANSFER",State="Issued",Quantity=1,PaidOn=new(2026,1,1),PaidAmount="100",PaymentParts=[new(own,"40","0"),new(original.Id,"60","0")],Tickets=[ticket]};
  var saved=await Data(await Write(f.Client,"/concerts",Scene() with{Orders=[order]}));var detail=await Data(await f.Client.GetAsync("/api/concerts/"+saved.GetProperty("id").GetString()));var report=detail.GetProperty("report");Assert.Equal("40.00",report.GetProperty("personalNetCost").GetString());Assert.Equal("20.00",report.GetProperty("ticketTransfers").GetProperty("netRecovery").GetString());Assert.Equal("20.00",report.GetProperty("finalPersonalCost").GetString());Assert.Equal("60.00",report.GetProperty("ticketTransfers").GetProperty("rows")[0].GetProperty("advanceSettlement").GetString());Assert.Equal("0.00",report.GetProperty("pendingAdvances").GetString());
  var body=Scene() with{Orders=[order with{Tickets=[ticket with{Outcome=new("Unused","未到场")}]}]};Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/"+saved.GetProperty("id").GetString(),body,saved.GetProperty("version").GetString()!,put:true)).StatusCode);
  body=body with{Orders=[body.Orders[0] with{Tickets=[body.Orders[0].Tickets![0] with{PersonalShare="40"}]}]};await Data(await Write(f.Client,"/concerts/"+saved.GetProperty("id").GetString(),body,saved.GetProperty("version").GetString()!,put:true));report=(await Data(await f.Client.GetAsync("/api/concerts/"+saved.GetProperty("id").GetString()))).GetProperty("report");Assert.Equal("20.00",report.GetProperty("unusedBurden").GetString());
 }
 [ProfileSqlFact] public async Task IndividualCostArtistOverridesKeepRefundCentsAndInterestReportConsistent() {
  await using var f=await LifecycleFixture.Create();async Task<string> Artist(string name)=>(await Data(await Write(f.Client,"/concerts/interests/topics",new InterestTopic(name,"Artist","")))).GetProperty("id").GetString()!;var a=await Artist("艺人甲");var b=await Artist("艺人乙");var pay=await f.Tx("Expense","100");var refund=await f.Tx("Refund","33.33",pay);var cost=new ConcertCost(Guid.NewGuid().ToString(),"Ticket",pay,null,"100","本人","本人",new("Split",[new(b,100)]));var scene=Scene() with{ArtistAllocation=new("Split",[new(a,100)]),Costs=[cost],Refunds=[new(Guid.NewGuid().ToString(),cost.Id,"Partial","33.33","0",refund,"33.33","")]};var saved=await Data(await Write(f.Client,"/concerts",scene));var id=saved.GetProperty("id").GetString()!;
  var report=(await Data(await f.Client.GetAsync("/api/concerts/"+id))).GetProperty("report");Assert.Equal("66.67",report.GetProperty("artistAttribution").EnumerateArray().Single(x=>x.GetProperty("artistId").GetString()==b).GetProperty("personalNetCost").GetString());
  var interest=await Data(await f.Client.GetAsync("/api/concerts/interests/report?currency=CNY&year=2026&artist="+b));Assert.Equal("66.67",interest.GetProperty("totals").GetProperty("net").GetString());
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/"+id,scene with{Costs=[cost with{Amount="100.001"}]},saved.GetProperty("version").GetString()!,put:true)).StatusCode);
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/"+id,scene with{Currency="USD"},saved.GetProperty("version").GetString()!,put:true)).StatusCode);
 }
